    switch (timeUnit) {
        case NANOS :
            return (mills * NANOS_PER_MILLISECOND) + nanosOfMillisecond;
        case MICROS :
            return (mills * MICROS_PER_MILLISECOND) + (nanosOfMillisecond / NANOS_PER_MICROSECONDS);
        case MILLIS :
            return mills;
        default :
