/**
 * The dictionary, if this column has dictionary encoding.
 */
private final ParquetDataColumnReader dictionary;

/**
 * Maximum definition level for this column.
 */
private final int maxDefLevel;

/**
 * Total number of values read.
 */
private long valuesRead;

/**
 * value that indicates the end of the current page. That is, if valuesRead ==
 * endOfPageValueCount, we are at the end of the page.
 */
private long endOfPageValueCount;

/**
 * If true, the current page is dictionary encoded.
 */
private boolean isCurrentPageDictionaryEncoded;

/**
 * Total values in the current page.
 */
private int pageValueCount;

setters:
private void initDataReader(Encoding dataEncoding, ByteBufferInputStream in, int valueCount) throws IOException {
    this.pageValueCount = valueCount;
    this.endOfPageValueCount = valuesRead + pageValueCount;
    if (dataEncoding.usesDictionary()) {
        this.dataColumn = null;
        if (dictionary == null) {
            throw new IOException(String.format("Could not read page in col %s because the dictionary was missing for encoding %s.", descriptor, dataEncoding));
        }
        dataColumn = ParquetDataColumnReaderFactory.getDataColumnReaderByType(type.asPrimitiveType(), dataEncoding.getDictionaryBasedValuesReader(descriptor, VALUES, dictionary.getDictionary()), isUtcTimestamp);
        this.isCurrentPageDictionaryEncoded = true;
    } else {
        dataColumn = ParquetDataColumnReaderFactory.getDataColumnReaderByType(type.asPrimitiveType(), dataEncoding.getValuesReader(descriptor, VALUES), isUtcTimestamp);
        this.isCurrentPageDictionaryEncoded = false;
    }
    try {
        dataColumn.initFromPage(pageValueCount, in);
    } catch (IOException e) {
        throw new IOException(String.format("Could not read page in col %s.", descriptor), e);
    }
}

private void readAndSaveRepetitionAndDefinitionLevels() {
    // get the values of repetition and definitionLevel
    repetitionLevel = repetitionLevelColumn.nextInt();
    definitionLevel = definitionLevelColumn.nextInt();
    valuesRead++;
    repetitionLevelList.add(repetitionLevel);
    definitionLevelList.add(definitionLevel);
}

protected void readPage() {
    DataPage page = pageReader.readPage();
    if (page == null) {
        return;
    }
    page.accept(new DataPage.Visitor<Void>() {
        @Override
        public Void visit(DataPageV1 dataPageV1) {
            readPageV1(dataPageV1);
            return null;
        }

        @Override
        public Void visit(DataPageV2 dataPageV2) {
            readPageV2(dataPageV2);
            return null;
        }
    });
}

private void readPageV1(DataPageV1 page) {
    ValuesReader rlReader = page.getRlEncoding().getValuesReader(descriptor, REPETITION_LEVEL);
    ValuesReader dlReader = page.getDlEncoding().getValuesReader(descriptor, DEFINITION_LEVEL);
    this.repetitionLevelColumn = new ValuesReaderIntIterator(rlReader);
    this.definitionLevelColumn = new ValuesReaderIntIterator(dlReader);
    try {
        BytesInput bytes = page.getBytes();
        LOG.debug("Page size {}  bytes and {} records.", bytes.size(), pageValueCount);
        ByteBufferInputStream in = bytes.toInputStream();
        LOG.debug("Reading repetition levels at {}.", in.position());
        rlReader.initFromPage(pageValueCount, in);
        LOG.debug("Reading definition levels at {}.", in.position());
        dlReader.initFromPage(pageValueCount, in);
        LOG.debug("Reading data at {}.", in.position());
        initDataReader(page.getValueEncoding(), in, page.getValueCount());
    } catch (IOException e) {
        throw new ParquetDecodingException(String.format("Could not read page %s in col %s.", page, descriptor), e);
    }
}

private void readPageV2(DataPageV2 page) {
    this.pageValueCount = page.getValueCount();
    this.repetitionLevelColumn = newRLEIterator(descriptor.getMaxRepetitionLevel(), page.getRepetitionLevels());
    this.definitionLevelColumn = newRLEIterator(descriptor.getMaxDefinitionLevel(), page.getDefinitionLevels());
    try {
        LOG.debug("Page data size {} bytes and {} records.", page.getData().size(), pageValueCount);
        initDataReader(page.getDataEncoding(), page.getData().toInputStream(), page.getValueCount());
    } catch (IOException e) {
        throw new ParquetDecodingException(String.format("Could not read page %s in col %s.", page, descriptor), e);
    }
}

