        return new RLEIntIterator(// PATH: Test should invoke the next BytesUtils.getWidthFromMaxInt(...) [step in execution path]
        new RunLengthBitPackingHybridDecoder(BytesUtils.getWidthFromMaxInt(maxLevel), new ByteArrayInputStream(bytes.toByteArray())));
